@st.cache_data(show_spinner=False)
def load_bank(file_mtime: int):
    """Referensi soal diambil dari workbook pengguna, bukan pertanyaan buatan."""
    _ = file_mtime
    book = pd.ExcelFile(DATA_PATH)
    if "Semua_Data" in book.sheet_names:
        df = pd.read_excel(book, sheet_name="Semua_Data")
    elif {"Training", "Testing"}.issubset(book.sheet_names):
        df = pd.concat([
            pd.read_excel(book, sheet_name="Training"),
            pd.read_excel(book, sheet_name="Testing"),
        ], ignore_index=True)
    else:
        raise ValueError("Excel harus memiliki sheet Semua_Data atau Training + Testing.")
    df = siap_dataset(df)
    return df, bank_dari_dataset(df)


@st.cache_data(show_spinner=False)
def load_dictionary(file_mtime: int):
    _ = file_mtime
    return muat_kamus(KAMUS_PATH)


@st.cache_resource(show_spinner=" Mengunduh/memuat XLM-RoBERTa-base (pertama kali lebih lama)...")
def load_encoder():
    import torch
    from transformers import AutoTokenizer, XLMRobertaModel
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    tokenizer = AutoTokenizer.from_pretrained(MODEL_NAME)
    model = XLMRobertaModel.from_pretrained(MODEL_NAME).to(device)
    model.eval()  # tidak dilatih dan dropout dimatikan
    return tokenizer, model, device


def embedding_bersama(texts: list[str], kamus: dict[str, str]) -> np.ndarray:
    """CLS [0] 768-d, padding=max_length 512, no_grad; cache per sesi."""
    import torch

    tokenizer, model, device = load_encoder()
    session_cache = st.session_state.setdefault("cache_vektor", {})
    bersih = [pra_pemrosesan(t, kamus) for t in texts]
    unik = list(dict.fromkeys(bersih))
    hilang = [t for t in unik if t not in session_cache]
    for txt in hilang:
        if not txt.strip():
            session_cache[txt] = np.zeros(int(model.config.hidden_size), dtype=np.float32)
    nonempty = [t for t in hilang if t.strip()]
    batch_size = 6 if device.type == "cuda" else 1  # lebih aman untuk RAM laptop
    prog = st.progress(0, text="Mengubah jawaban menjadi embedding XLM-RoBERTa...") if nonempty else None
    for i in range(0, len(nonempty), batch_size):
        group = nonempty[i:i + batch_size]
        tok = tokenizer(group, padding="max_length", truncation=True, max_length=MAX_LENGTH, return_tensors="pt")
        tok = {k: v.to(device) for k, v in tok.items()}
        with torch.inference_mode():
            # Token pertama <s>, sama seperti kode Colab sumber.
            tensor = model(**tok).last_hidden_state[:, 0, :]
        for t, vec in zip(group, tensor.detach().cpu().numpy()):
            session_cache[t] = np.asarray(vec, dtype=np.float32)
        if prog:
            prog.progress(min(1.0, (i + len(group)) / len(nonempty)), text=f"Ekstraksi embedding: {min(i + len(group), len(nonempty))}/{len(nonempty)} teks")
    if prog:
        prog.empty()
    return np.vstack([session_cache[t] for t in bersih]).astype(np.float32)


def hitung_skor(df: pd.DataFrame, kamus: dict[str, str]) -> pd.DataFrame:
    """Mengembalikan skor langsung dari cosine similarity."""
    df = siap_dataset(df)
    if df.empty:
        raise ValueError("Belum ada jawaban siswa untuk dinilai.")
    if df["Jawaban_Siswa"].str.strip().eq("").any():
        raise ValueError("Ada jawaban siswa kosong. Lengkapi atau keluarkan baris kosong dahulu.")
    if df["Kunci_Guru"].str.strip().eq("").any():
        raise ValueError("Kunci guru tidak boleh kosong.")
    n = len(df)
    embeddings = embedding_bersama(
        df["Jawaban_Siswa"].tolist() + df["Kunci_Guru"].tolist(), kamus
    )
    cosine = similarity_rows(embeddings[:n], embeddings[n:])
    hasil = df.copy()
    hasil["Cosine_Similarity"] = cosine
    hasil["Kemiripan_Persen"] = cosine * 100.0
    hasil["Skor_Kontinu"] = hasil["Cosine_Similarity"] * hasil["Bobot"]
    # np.round(...*2)/2 adalah pembulatan rubrik 0,5 sesuai notebook
    hasil["Skor_Rubrik"] = np.maximum(0.0, np.round(hasil["Skor_Kontinu"] * 2.0) / 2.0)
    if "Skor" in hasil.columns:
        hasil["Selisih_dari_Guru"] = np.abs(hasil["Skor"] - hasil["Skor_Kontinu"])
    return hasil


def xlsx_bytes(df: pd.DataFrame, ringkasan: pd.DataFrame | None = None) -> bytes:
    """Ekspor dengan perlindungan karakter pemicu formula untuk teks siswa."""
    safe = df.copy()
    for col in safe.select_dtypes(include="object").columns:
        safe[col] = safe[col].map(
            lambda x: "'" + x if isinstance(x, str) and x[:1] in ("=", "+", "-", "@", "\t", "\r") else x
        )
    memory = io.BytesIO()
    with pd.ExcelWriter(memory, engine="openpyxl") as writer:
        safe.to_excel(writer, index=False, sheet_name="Penilaian_Cosine")
        if ringkasan is not None:
            ringkasan = ringkasan.copy()
            for col in ringkasan.select_dtypes(include="object").columns:
                ringkasan[col] = ringkasan[col].map(
                    lambda x: "'" + x if isinstance(x, str) and x[:1] in ("=", "+", "-", "@", "\t", "\r") else x
                )
            ringkasan.to_excel(writer, index=False, sheet_name="Ringkasan_Siswa")
            summary_sheet = writer.sheets["Ringkasan_Siswa"]
            for cells in summary_sheet.columns:
                summary_sheet.column_dimensions[cells[0].column_letter].width = 30
        sheet = writer.sheets["Penilaian_Cosine"]
        sheet.freeze_panes = "A2"
        sheet.auto_filter.ref = sheet.dimensions
        for letter, w in {"A":10,"B":18,"C":10,"D":13,"E":54,"F":66,"G":66,"H":11,"I":11,"J":20,"K":20,"L":17,"M":17}.items():
            sheet.column_dimensions[letter].width = w
        from openpyxl.styles import Alignment, Font, PatternFill
        for cell in sheet[1]:
            cell.fill = PatternFill("solid", fgColor="0867BB")
            cell.font = Font(color="FFFFFF", bold=True)
            cell.alignment = Alignment(wrap_text=True)
    return memory.getvalue()


def tampil_hasil(df: pd.DataFrame, file_name: str):
    if df is None or len(df) == 0:
        return
    c1, c2, c3 = st.columns(3)
    with c1:
        st.metric(" Jawaban dinilai", f"{len(df):,}")
    with c2:
        st.metric(" Rata-rata kemiripan", f"{df['Kemiripan_Persen'].mean():.2f}%")
    with c3:
        st.metric("⭐ Rata-rata skor rubrik", f"{df['Skor_Rubrik'].mean():.2f}")
    cols = ["Kode_Soal", "Nama", "Bobot", "Kemiripan_Persen", "Skor_Kontinu", "Skor_Rubrik", "Kelas", "Absen", "Jawaban_Siswa"]
    if "Skor" in df.columns:
        cols.extend(["Skor", "Selisih_dari_Guru"])
    cols = [c for c in cols if c in df.columns]
    nice = {
        "Kode_Soal": "Kode Soal", "Nama": "Nama Siswa", "Kelas": "Kelas", "Absen": "Absen",
        "Jawaban_Siswa": "Jawaban Siswa", "Bobot": "Bobot", "Kemiripan_Persen": "Cosine (%)",
        "Skor_Kontinu": "Skor Kontinu", "Skor_Rubrik": "Skor Rubrik", "Skor": "Skor Guru",
        "Selisih_dari_Guru": "Selisih Absolut",
    }
    fmt = {"Cosine (%)":"%.2f", "Skor Kontinu":"%.4f", "Skor Rubrik":"%.2f", "Bobot":"%.2f", "Selisih Absolut":"%.4f"}
    view = df[cols].rename(columns=nice)
    st.dataframe(view, use_container_width=True, hide_index=True,
                 column_config={"Jawaban Siswa": st.column_config.TextColumn(width="large")})
    st.download_button("⬇ Unduh hasil penilaian Excel", data=xlsx_bytes(df),
                       file_name=file_name, mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                       use_container_width=True, key=f"down_{file_name}")
    if len(df) > 1:
        with st.expander(" Lihat distribusi hasil penilaian"):
            chart = df[["Skor_Rubrik"]].value_counts().reset_index(name="Jumlah Jawaban")
            chart = chart.sort_values("Skor_Rubrik").set_index("Skor_Rubrik")
            st.bar_chart(chart, color="#6bb2e4", height=270)
            st.caption("Skor rubrik adalah pembulatan kelipatan 0,5 dari skor cosine × bobot.")


def jawaban_satu_siswa(dataset: pd.DataFrame, identitas: tuple) -> pd.DataFrame:
    """Pilih identitas lengkap; cegah nilai akhir dari soal hilang/duplikat."""
    cols = ["Nama", "Kelas", "Absen"]
    mask = (dataset[cols].astype(str) == pd.Series(identitas, index=cols)).all(axis=1)
    selected = dataset.loc[mask].copy().sort_values("Kode_Soal").reset_index(drop=True)
    if selected.empty:
        raise ValueError("Siswa tidak ditemukan pada dataset.")
    if selected["Kode_Soal"].isna().any():
        raise ValueError("Terdapat kode soal kosong atau tidak valid.")
    duplicates = selected.loc[selected["Kode_Soal"].duplicated(), "Kode_Soal"].tolist()
    if duplicates:
        raise ValueError(f"Kode soal duplikat: {duplicates}. Periksa dataset dahulu.")
    expected = set(range(1, 38))
    actual = set(selected["Kode_Soal"].tolist())
    if actual != expected:
        raise ValueError(f"Data harus lengkap soal 1–37. Soal hilang: {sorted(expected-actual)}; kode tambahan: {sorted(actual-expected)}.")
    return selected


def ringkasan_satu_siswa(hasil: pd.DataFrame) -> pd.DataFrame:
    """Jumlahkan Skor tersimpan pada dataset, bukan prediksi baru model."""
    if len(hasil) != 37 or set(hasil["Kode_Soal"].tolist()) != set(range(1, 38)):
        raise ValueError("Nilai akhir memerlukan tepat 37 soal unik, dari nomor 1 sampai 37.")
    if "Skor" not in hasil.columns:
        raise ValueError("Kolom Skor tidak tersedia pada dataset.")
    scores = pd.to_numeric(hasil["Skor"], errors="coerce")
    if not np.isfinite(scores.to_numpy(dtype=float)).all() or scores.lt(0).any():
        raise ValueError("Skor seluruh 37 soal harus berupa angka valid dan tidak negatif.")
    if scores.gt(hasil["Bobot"]).any():
        raise ValueError("Ada skor melebihi bobot soal. Periksa dataset terlebih dahulu.")
    total = float(scores.sum())
    average = total / 37
    score_100 = average * 100
    return pd.DataFrame([{
        "Nama": hasil.iloc[0]["Nama"], "Kelas": hasil.iloc[0]["Kelas"],
        "Absen": hasil.iloc[0]["Absen"], "Jumlah_Soal": 37,
        "Sumber_Skor": "Kolom Skor pada dataset",
        "Total_Skor": total, "Rata_Rata_Skor_37": average,
        "Nilai_Sebelum_Pembulatan": score_100,
        "Nilai_Akhir_100": int(np.floor(score_100 + 0.5)),
    }])


